CREATE OR REPLACE JSON RELATIONAL DUALITY VIEW service_orders_dv AS
    SELECT JSON {
        '_id'         : r.order_id,
        'subscriberId'  : r.subscriber_id,
        'siteId' : r.site_id,
        'periodStart'     : r.period_start,
        'periodEnd'    : r.period_end,
        'status'      : r.order_status,
        'total'       : r.order_total,
        'activationFee': r.activation_fee,
        'demandScore' : r.demand_score,
        'createdAt'   : r.created_at,
        'items' : [
            SELECT JSON {
                'orderLineId'    : rn.order_line_id,
                'planId' : rn.plan_id,
                'connectionCount'  : rn.connection_count,
                'monthlyFee' : rn.monthly_fee
            }
            FROM service_order_lines rn WITH UPDATE
            WHERE rn.order_id = r.order_id
        ]
    }
    FROM service_orders r WITH UPDATE;

CREATE PROPERTY GRAPH activation_fraud_network
  VERTEX TABLES (
    activation_entities KEY (entity_id)
      LABEL entity
      PROPERTIES (
        entity_id,
        entity_key,
        display_name,
        entity_type,
        risk_score,
        risk_level,
        channel,
        total_amount,
        event_count,
        is_confirmed_fraud
      ),
    activation_cases KEY (case_id)
      LABEL activation_case
      PROPERTIES (
        case_id,
        case_ref,
        case_type,
        status,
        risk_score,
        loss_amount,
        event_count
      )
  )
  EDGE TABLES (
    activation_relationships KEY (relationship_id)
      SOURCE KEY (from_entity)
        REFERENCES activation_entities (entity_id)
      DESTINATION KEY (to_entity)
        REFERENCES activation_entities (entity_id)
      LABEL related_to
      PROPERTIES (
        relationship_type,
        strength,
        event_count,
        total_amount
      ),
    activation_case_entities KEY (case_entity_id)
      SOURCE KEY (case_id)
        REFERENCES activation_cases (case_id)
      DESTINATION KEY (entity_id)
        REFERENCES activation_entities (entity_id)
      LABEL contains_entity
      PROPERTIES (
        role,
        evidence_score
      )
  );

PROMPT Creating telecommunications reporting and demand-training views
CREATE OR REPLACE VIEW service_plans_v AS
SELECT plan_id, plan_name, site_id, category AS plan_category
FROM service_plans;

CREATE OR REPLACE VIEW network_sites_v AS
SELECT site_id, site_name, city, state_province
FROM network_sites;

CREATE OR REPLACE VIEW service_alerts_v AS
SELECT report_id AS alert_id, severity_score, affected_subscribers, service_cases_opened
FROM subscriber_reports;

/* Fixed September 2026 snapshot [September 1, October 1).
   Aggregate support observation intervals and accepted order lines separately.
   Monthly charges include confirmed/active/completed orders, excluding activation fees.
   Busy intervals: utilization 60..79; congested intervals: utilization >=80.
   Synthetic teaching target SURGE: >=45 connections ordered and >=2 busy or
   congested observation intervals. Otherwise STABLE. This is a same-window
   demand classification, not a measured forecast of future activations.
*/
CREATE OR REPLACE VIEW oml_plan_demand_training_v AS
WITH post_metrics AS (
  SELECT pom.plan_id,
         COUNT(*) AS total_reports,
         AVG(gp.sentiment) AS avg_sentiment,
         SUM(gp.dropped_sessions) AS dropped_sessions,
         SUM(gp.outage_minutes) AS outage_minutes,
         SUM(gp.data_volume_gb) AS data_volume_gb,
         AVG(gp.utilization_pct) AS avg_utilization_pct,
         SUM(CASE WHEN gp.utilization_pct >= 80 THEN 1 ELSE 0 END) AS congested_intervals,
         SUM(CASE WHEN gp.utilization_pct >= 60 AND gp.utilization_pct < 80 THEN 1 ELSE 0 END) AS busy_intervals
  FROM report_plan_mentions pom
  JOIN subscriber_reports gp ON gp.report_id = pom.report_id
  WHERE gp.reported_at >= TIMESTAMP '2026-09-01 00:00:00'
    AND gp.reported_at < TIMESTAMP '2026-10-01 00:00:00'
  GROUP BY pom.plan_id
), activation_metrics AS (
  SELECT rn.plan_id,
         SUM(rn.connection_count) AS connections_ordered,
         SUM(rn.line_total) AS monthly_charges
  FROM service_order_lines rn
  JOIN service_orders r ON r.order_id = rn.order_id
  WHERE r.order_status IN ('confirmed', 'active', 'completed')
    AND r.period_start >= DATE '2026-09-01'
    AND r.period_start < DATE '2026-10-01'
  GROUP BY rn.plan_id
)
SELECT so.plan_id, so.category, so.monthly_fee,
       NVL(pm.total_reports, 0) AS total_reports,
       NVL(pm.avg_sentiment, 0) AS avg_sentiment,
       NVL(pm.dropped_sessions, 0) AS dropped_sessions,
       NVL(pm.outage_minutes, 0) AS outage_minutes,
       NVL(pm.data_volume_gb, 0) AS data_volume_gb,
       NVL(pm.avg_utilization_pct, 0) AS avg_utilization_pct,
       NVL(pm.congested_intervals, 0) AS congested_intervals,
       NVL(pm.busy_intervals, 0) AS busy_intervals,
       NVL(bm.connections_ordered, 0) AS connections_ordered,
       NVL(bm.monthly_charges, 0) AS monthly_charges,
       CAST(CASE WHEN NVL(bm.connections_ordered, 0) >= 45
                      AND NVL(pm.congested_intervals, 0) + NVL(pm.busy_intervals, 0) >= 2
                 THEN 'SURGE' ELSE 'STABLE' END AS VARCHAR2(10)) AS surge_label
FROM service_plans so
LEFT JOIN post_metrics pm ON pm.plan_id = so.plan_id
LEFT JOIN activation_metrics bm ON bm.plan_id = so.plan_id
WHERE so.is_active = 1;

PROMPT Embedding SEER Telecomms plans with the shared 384-dimension model
-- Same model and text recipe as Lab 3; the learner adds the separate column.
SELECT plan_id,
       VECTOR_EMBEDDING(ADMIN.ALL_MINILM_L12_V2 USING
         plan_name || '. Category: ' || category || '. Subcategory: ' || subcategory AS DATA)
FROM service_plans;
COMMIT;

