PROMPT Configuring the existing GENAI profile for telecommunications
-- Preserve provider, credential, compartment and region from setup.
BEGIN
  DBMS_CLOUD_AI.SET_ATTRIBUTE(
    profile_name => 'GENAI',
    attribute_name => 'object_list',
    attribute_value => '[{"owner":"LLUSER","name":"SERVICE_PLANS"},
                         {"owner":"LLUSER","name":"SERVICE_ORDERS"},
                         {"owner":"LLUSER","name":"SERVICE_ORDER_LINES"},
                         {"owner":"LLUSER","name":"SUBSCRIBERS"}]');
  DBMS_CLOUD_AI.SET_PROFILE('GENAI');
END;
/

PROMPT Preparing the agent reasoning profile
-- Use a separate profile for agent reasoning; GENAI remains the SQL tool profile.
-- Validated with OCI Llama 3.3 70B on-demand in Chicago.
DECLARE
  l_count NUMBER;
  l_attributes CLOB;
  l_provider VARCHAR2(128);
  l_credential VARCHAR2(4000);
  l_compartment VARCHAR2(4000);
BEGIN
  SELECT COUNT(*) INTO l_count
  FROM user_cloud_ai_profiles WHERE profile_name = 'GENAI_AGENT';
  IF l_count = 0 THEN
    SELECT MAX(CASE WHEN attribute_name = 'provider' THEN CAST(attribute_value AS VARCHAR2(4000)) END),
           MAX(CASE WHEN attribute_name = 'credential_name' THEN CAST(attribute_value AS VARCHAR2(4000)) END),
           MAX(CASE WHEN attribute_name = 'oci_compartment_id' THEN CAST(attribute_value AS VARCHAR2(4000)) END)
    INTO l_provider, l_credential, l_compartment
    FROM user_cloud_ai_profile_attributes WHERE profile_name = 'GENAI';
    IF NVL(LOWER(l_provider), 'missing') <> 'oci' OR l_credential IS NULL OR l_compartment IS NULL THEN
      RAISE_APPLICATION_ERROR(-20007, 'GENAI must provide OCI credential and compartment attributes for GENAI_AGENT setup.');
    END IF;
    SELECT JSON_OBJECT(
        'provider' VALUE 'oci',
        'credential_name' VALUE l_credential,
        'oci_compartment_id' VALUE l_compartment,
        'region' VALUE 'us-chicago-1',
        'model' VALUE 'meta.llama-3.3-70b-instruct',
        'oci_apiformat' VALUE 'GENERIC',
        'temperature' VALUE 0,
        'max_tokens' VALUE 4096 RETURNING CLOB)
    INTO l_attributes FROM dual;
    DBMS_CLOUD_AI.CREATE_PROFILE(
      profile_name => 'GENAI_AGENT', attributes => l_attributes);
  END IF;
END;
/

PROMPT Checking loaded telecommunications data and lab prerequisites
DECLARE
  l_count NUMBER;
  PROCEDURE require_zero(p_count NUMBER, p_message VARCHAR2) IS
  BEGIN
    IF p_count <> 0 THEN RAISE_APPLICATION_ERROR(-20010, p_message); END IF;
  END;
BEGIN
  SELECT COUNT(*) INTO l_count
  FROM service_orders r
  LEFT JOIN (
    SELECT order_id, SUM(connection_count) AS connections, SUM(line_total) AS recurring_total
    FROM service_order_lines GROUP BY order_id
  ) n ON n.order_id = r.order_id
  WHERE n.order_id IS NULL
     OR n.recurring_total + r.activation_fee <> r.order_total;
  require_zero(l_count, 'Service order totals do not equal monthly charges plus activation fees.');

  SELECT COUNT(*) INTO l_count
  FROM service_order_lines rn
  JOIN service_orders r ON r.order_id = rn.order_id
  JOIN service_plans so ON so.plan_id = rn.plan_id
  WHERE so.site_id <> r.site_id;
  require_zero(l_count, 'A service plan belongs to a different network site.');

  SELECT COUNT(*) INTO l_count FROM service_orders
    WHERE period_end <> ADD_MONTHS(period_start, 1);
  require_zero(l_count, 'Fixture service periods must span one month.');

  SELECT COUNT(*) INTO l_count FROM service_orders WHERE order_id = 900001;
  require_zero(l_count, 'Lab 2 service order ID 900001 must remain unused.');
  SELECT COUNT(*) INTO l_count FROM service_order_lines WHERE order_line_id = 990001;
  require_zero(l_count, 'Lab 2 monthly service-charge ID 990001 must remain unused.');
  SELECT COUNT(*) INTO l_count FROM service_plans
    WHERE plan_id = 1 AND site_id = 1 AND monthly_fee = 125;
  require_zero(l_count - 1, 'Lab 2 requires plan 1 at site 1 priced at USD 125.');
  SELECT COUNT(*) INTO l_count FROM subscribers WHERE subscriber_id = 1;
  require_zero(l_count - 1, 'Lab 2 subscriber 1 is missing.');

  SELECT COUNT(*) INTO l_count FROM plan_embeddings;
  require_zero(l_count - 192, 'Expected 192 preloaded plan embeddings.');
  SELECT COUNT(*) INTO l_count FROM plan_embeddings
    WHERE VECTOR_DIMENSION_COUNT(embedding) <> 384;
  require_zero(l_count, 'Plan embedding dimension must be 384.');
  SELECT COUNT(*) INTO l_count FROM user_tab_columns
    WHERE table_name = 'SERVICE_PLANS' AND column_name = 'PLAN_EMBEDDING';
  require_zero(l_count, 'Leave SERVICE_PLANS.PLAN_EMBEDDING for the learner in Lab 3.');

  SELECT COUNT(*) INTO l_count FROM oml_plan_demand_training_v;
  require_zero(l_count - 192, 'Expected one training row for each of 192 active plans.');
  SELECT COUNT(*) INTO l_count FROM oml_plan_demand_training_v WHERE surge_label = 'SURGE';
  require_zero(l_count - 96, 'Expected 96 synthetic SURGE examples.');
  SELECT COUNT(*) INTO l_count FROM oml_plan_demand_training_v WHERE surge_label = 'STABLE';
  require_zero(l_count - 96, 'Expected 96 synthetic STABLE examples.');

  SELECT COUNT(*) INTO l_count FROM (
    SELECT SDO_GEOM.VALIDATE_GEOMETRY_WITH_CONTEXT(location, 0.005) AS valid FROM network_sites
    UNION ALL
    SELECT SDO_GEOM.VALIDATE_GEOMETRY_WITH_CONTEXT(location, 0.005) FROM subscribers
    UNION ALL
    SELECT SDO_GEOM.VALIDATE_GEOMETRY_WITH_CONTEXT(boundary, 0.005) FROM network_regions
  ) WHERE valid <> 'TRUE' OR valid IS NULL;
  require_zero(l_count, 'A network site, subscriber or network-region geometry is invalid.');

  SELECT COUNT(*) INTO l_count FROM GRAPH_TABLE (
    activation_fraud_network
    MATCH (a IS entity)-[e IS related_to]->(b IS entity)
    WHERE a.entity_key = 'ORD-8841'
    COLUMNS (b.entity_key AS linked_entity)
  );
  IF l_count = 0 THEN RAISE_APPLICATION_ERROR(-20011, 'Activation graph seed has no outgoing evidence.'); END IF;

  SELECT COUNT(*) INTO l_count FROM user_objects
    WHERE status = 'INVALID' AND object_name IN (
      'SERVICE_PLANS_V', 'NETWORK_SITES_V', 'SERVICE_ALERTS_V',
      'OML_PLAN_DEMAND_TRAINING_V', 'SERVICE_ORDERS_DV', 'ACTIVATION_FRAUD_NETWORK');
  require_zero(l_count, 'A telecommunications view or graph is invalid.');
  SELECT COUNT(*) INTO l_count FROM service_orders_dv;
  require_zero(l_count - 3843, 'Expected one JSON document per loaded service order.');
  DBMS_OUTPUT.PUT_LINE('Telecommunications data, vector, spatial, duality and SQL graph assertions passed.');
END;
/

/* OPTIONAL GRAPH STUDIO / PGX SETUP
   The primary activation notebook uses the SQL property graph created above.
   The optional airtime notebook instead requests AIRTIME_GRAPH as PG_PGQL.
   A plain SQLcl session does not parse PGQL DDL. Before importing/running the
   optional notebook, open Graph Studio as LLUSER, add a PGQL (RDBMS) notebook
   paragraph beginning with %pgql-rdbms, and run the following statement.
   Alternatively, use an installed SQLcl
   PGQL plug-in with PGQL mode enabled. Do not paste it into a SQL worksheet.
   The statement is intentionally commented here so the supplied SQLcl
   Terraform invocation works without an additional plug-in.

   CREATE PROPERTY GRAPH airtime_graph
     VERTEX TABLES (
       prepaid_accounts KEY (account_id)
         LABEL account PROPERTIES (account_id, subscriber_id, name)
     )
     EDGE TABLES (
       airtime_transfers KEY (transfer_id)
         SOURCE KEY (from_account_id) REFERENCES prepaid_accounts (account_id)
         DESTINATION KEY (to_account_id) REFERENCES prepaid_accounts (account_id)
         LABEL TRANSFERS
         PROPERTIES (transfer_id, from_account_id, to_account_id, minutes, description)
     ) OPTIONS (PG_PGQL);

   Then load it from the optional notebook with:
     session.read_graph_by_name("AIRTIME_GRAPH", "pg_pgql")
   This additional graph is not claimed as created by the SQL loader.
*/
COMMIT;
